import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, positionLocal, normalLocal, texture, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Vector3, Color, DirectionalLight } = ctx.THREE;

  const group = new Group();
  const cleanupTasks = [];

  // ---------------------------------------------------------
  // Palette & Colors
  // ---------------------------------------------------------
  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const colInk = new Color(colors.ink);
  const colAccent = new Color(colors.accent);
  const colSurface = new Color(colors.surface);
  const colPaper = new Color(colors.paper);

  // ---------------------------------------------------------
  // Stage Background (Prevent flat void)
  // ---------------------------------------------------------
  const bgGeom = new PlaneGeometry(8, 6);
  // Elegant modern metal plate backdrop
  const bgMat = new MeshStandardNodeMaterial({
    roughness: 0.6,
    metalness: 0.5,
  });
  // Vertical gradient emulation with simple node
  const topColor = colInk.clone().lerp(colSurface, 0.4);
  const bottomColor = colSurface;
  bgMat.colorNode = uv().y.mix(bottomColor, topColor);

  const bgMesh = new Mesh(bgGeom, bgMat);
  bgMesh.position.set(0, 0, -2.5);
  group.add(bgMesh);

  // ---------------------------------------------------------
  // Local Lighting Setup
  // ---------------------------------------------------------
  const localKey = new DirectionalLight(colPaper, 1.2);
  localKey.position.set(2, 3, 4);
  group.add(localKey);

  const localRim = new DirectionalLight(colAccent, 0.9);
  localRim.position.set(-3, -2, 2);
  group.add(localRim);

  // ---------------------------------------------------------
  // Hero: Machined Ruler (Parallax Plane)
  // ---------------------------------------------------------
  // 64x64 segments for high quality displacement mapping
  const dividerGeom = new PlaneGeometry(4.5, 1.8, 64, 64);

  // Clean initial uniforms
  const uDisplacementScale = uniform(0.12);
  const uBaseColor = uniform(colPaper);

  const dividerMat = new MeshStandardNodeMaterial({
    roughness: 0.18,
    metalness: 0.85,
    clearcoat: 0.25,
    roughnessMap: null
  });

  const contentGroup = new Group();
  group.add(contentGroup);

  // Load textures securely through ctx interface
  const imageUrl = config.imageUrl ?? '/prism-mock/home/nodes/parallax-stack.png';
  const depthMapUrl = config.depthMapUrl ?? '/prism-mock/home/nodes/parallax-stack.depth.png';

  ctx.textureLoader.loadTexture(imageUrl).then((imgTex) => {
    dividerMat.colorNode = texture(imgTex, uv()).mul(uBaseColor);
  });

  ctx.textureLoader.loadTexture(depthMapUrl).then((depthTex) => {
    const tDepth = texture(depthTex, uv());
    dividerMat.positionNode = positionLocal.add(normalLocal.mul(tDepth.r.mul(uDisplacementScale)));
    dividerMat.needsUpdate = true;
  });

  const dividerMesh = new Mesh(dividerGeom, dividerMat);
  contentGroup.add(dividerMesh);

  // ---------------------------------------------------------
  // Interaction and Animations
  // ---------------------------------------------------------
  let targetRotationX = 0;
  let targetRotationY = 0;

  const onPointerMove = (e) => {
    if (e.pointer && e.pointer.x !== undefined) {
      targetRotationY = e.pointer.x * 0.12;
      targetRotationX = -e.pointer.y * 0.12;
    }
  };

  // GSAP Hover and Click Animations
  const onPointerOver = () => {
    gsap.to(contentGroup.position, {
      z: 0.15,
      y: 0.05,
      duration: 0.5,
      ease: 'power3.out'
    });
    gsap.to(uBaseColor.value, {
      r: colPaper.r * 1.05 + colAccent.r * 0.1,
      g: colPaper.g * 1.05 + colAccent.g * 0.1,
      b: colPaper.b * 1.05 + colAccent.b * 0.1,
      duration: 0.3
    });
  };

  const onPointerOut = () => {
    gsap.to(contentGroup.position, {
      z: 0,
      y: 0,
      duration: 0.6,
      ease: 'power2.out'
    });
    gsap.to(uBaseColor.value, {
      r: colPaper.r,
      g: colPaper.g,
      b: colPaper.b,
      duration: 0.5
    });
    targetRotationX = 0;
    targetRotationY = 0;
  };

  const onClick = () => {
    // Emit designated contract event
    ctx.emit('hub-features.select', { id: 'machined-rule' });

    // Click feedback curve with GSAP
    const tl = gsap.timeline();
    tl.to(contentGroup.scale, {
      x: 0.96,
      y: 0.96,
      z: 0.96,
      duration: 0.12,
      ease: 'back.out(2)'
    });
    tl.to(contentGroup.scale, {
      x: 1.0,
      y: 1.0,
      z: 1.0,
      duration: 0.35,
      ease: 'power4.out'
    });
  };

  // Map to modern standard event handlers
  group.userData.handlers = {
    pointermove: onPointerMove,
    pointerover: onPointerOver,
    pointerout: onPointerOut,
    click: onClick
  };

  // Tick loop manually for organic parallax response
  const clock = new ctx.THREE.Clock();
  let animationFrameId;

  const update = () => {
    animationFrameId = requestAnimationFrame(update);
    const dt = clock.getDelta();
    // Weighted settle dynamic interpolation
    contentGroup.rotation.x += (targetRotationX - contentGroup.rotation.x) * 4.5 * dt;
    contentGroup.rotation.y += (targetRotationY - contentGroup.rotation.y) * 4.5 * dt;
  };
  update();

  // ---------------------------------------------------------
  // Cleanup Hook
  // ---------------------------------------------------------
  group.userData.cleanup = () => {
    cancelAnimationFrame(animationFrameId);
    bgGeom.dispose();
    bgMat.dispose();
    dividerGeom.dispose();
    dividerMat.dispose();
    gsap.killTweensOf(contentGroup.position);
    gsap.killTweensOf(contentGroup.scale);
    gsap.killTweensOf(uBaseColor.value);
    cleanupTasks.forEach(task => task());
  };

  return group;
}
